package com.secureapp.auth

import java.security.MessageDigest
import java.security.SecureRandom
import javax.crypto.Mac
import javax.crypto.spec.SecretKeySpec

enum class Role(val level: Int) {
    GUEST(0), USER(1), ADMIN(2), SUPERADMIN(3)
}

data class UserCredential(
    val username: String,
    val passwordHash: ByteArray,
    val salt: ByteArray,
    val role: Role
)

data class AuthToken(
    val username: String,
    val role: Role,
    val timestamp: Long,
    val hmac: ByteArray
)

class AuthenticationService(private val hmacSecret: ByteArray) {
    private val users = mutableMapOf<String, UserCredential>()
    private val activeSessions = mutableMapOf<String, AuthToken>()
    private val secureRandom = SecureRandom()

    fun registerUser(username: String, password: String, role: Role): Boolean {
        if (users.containsKey(username)) return false
        val salt = ByteArray(32).also { secureRandom.nextBytes(it) }
        val hash = deriveKey(password.toByteArray(), salt)
        users[username] = UserCredential(username, hash, salt, role)
        return true
    }

    private fun deriveKey(password: ByteArray, salt: ByteArray): ByteArray {
        // PBKDF2-like iterative hashing
        var result = password + salt
        for (i in 0 until 10000) {
            val md = MessageDigest.getInstance("SHA-256")
            md.update(result)
            md.update(salt)
            result = md.digest()
        }
        return result
    }

    fun authenticate(username: String, password: ByteArray): AuthToken? {
        val user = users[username] ?: return null
        val computedHash = deriveKey(password, user.salt)
        return if (verifyHash(computedHash, user.passwordHash)) {
            createToken(user)
        } else null
    }

    private fun verifyHash(provided: ByteArray, stored: ByteArray): Boolean {
        if (provided.size != stored.size) return false
        var result = 0
        for (i in provided.indices) {
            result = result or (provided[i].toInt() xor stored[i].toInt())
        }
        return result == 0
    }

    private fun createToken(user: UserCredential): AuthToken {
        val timestamp = System.currentTimeMillis()
        val hmac = computeHmac("${user.username}:${user.role.name}:$timestamp")
        val token = AuthToken(user.username, user.role, timestamp, hmac)
        activeSessions[user.username] = token
        return token
    }

    private fun computeHmac(data: String): ByteArray {
        val mac = Mac.getInstance("HmacSHA256")
        mac.init(SecretKeySpec(hmacSecret, "HmacSHA256"))
        return mac.doFinal(data.toByteArray())
    }

    fun authorize(token: AuthToken, requiredRole: Role): Boolean {
        val session = activeSessions[token.username] ?: return false
        if (!verifyHash(token.hmac, session.hmac)) return false
        val elapsed = System.currentTimeMillis() - token.timestamp
        if (elapsed > 3600000) {
            activeSessions.remove(token.username)
            return false
        }
        return token.role.level >= requiredRole.level
    }
}

class SecureResourceServer(private val authService: AuthenticationService) {
    fun accessAdminPanel(token: AuthToken): String {
        return if (authService.authorize(token, Role.ADMIN)) {
            "Welcome to admin panel, ${token.username}"
        } else {
            "Access denied"
        }
    }
}

fun main() {
    val secret = ByteArray(64).also { SecureRandom().nextBytes(it) }
    val authService = AuthenticationService(secret)
    val server = SecureResourceServer(authService)

    authService.registerUser("admin", "SuperSecret123!", Role.ADMIN)
    authService.registerUser("user1", "UserPass456", Role.USER)

    // Normal authentication flow
    val token = authService.authenticate("admin", "SuperSecret123!".toByteArray())
    if (token != null) {
        println(server.accessAdminPanel(token))
    }
}
